class MembershipBoard:
    def __init__(self, teams):
        if not isinstance(teams, list):
            raise TypeError("teams must be a list")
        if any(not isinstance(team, str) for team in teams):
            raise TypeError("team names must be strings")
        if any(not team for team in teams) or len(set(teams)) != len(teams):
            raise ValueError("team names must be non-empty and unique")
        self._teams = tuple(teams)
        self._members = {}
        self._events = []

    @staticmethod
    def _text(value, label):
        if not isinstance(value, str):
            raise TypeError(f"{label} must be a string")
        if not value:
            raise ValueError(f"{label} must not be empty")

    def add_member(self, member_id):
        self._text(member_id, "member_id")
        if member_id in self._members:
            raise KeyError(member_id)
        self._members[member_id] = {"pending"}
        self._events.append(f"Welcome {member_id}")

    def verify(self, member_id):
        self._text(member_id, "member_id")
        if member_id not in self._members:
            raise KeyError(member_id)
        if "pending" not in self._members[member_id]:
            raise ValueError("member is already verified")
        self._members[member_id].remove("pending")
        self._members[member_id].update(("member", "unassigned"))

    def choose_team(self, member_id, team):
        self._text(member_id, "member_id")
        self._text(team, "team")
        if member_id not in self._members:
            raise KeyError(member_id)
        if team not in self._teams:
            raise ValueError("unknown team")
        current = self._members[member_id]
        if "member" not in current:
            raise ValueError("member is not verified")
        current.discard("pending")
        current.difference_update(self._teams)
        current.add(team)

    def roles(self, member_id):
        self._text(member_id, "member_id")
        if member_id not in self._members:
            raise KeyError(member_id)
        return tuple(sorted(self._members[member_id]))

    def events(self):
        return tuple(self._events)

